package com.primehr.rewardsrecognition.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="rr_hap_endorsement_event") public class RrHapEndorsementEvent extends RspAuditedEntity{public enum Status{PREPARED,ENDORSED,SUBMITTED,ACKNOWLEDGED,RETURNED,WITHDRAWN}@Column(name="award_record_id",nullable=false,length=36)private String awardRecordId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="external_reference",length=300)private String externalReference;@Column(nullable=false,length=3000)private String details;@Column(name="recorded_by",nullable=false,length=100)private String recordedBy;@Column(name="recorded_at",nullable=false)private Instant recordedAt;protected RrHapEndorsementEvent(){}public RrHapEndorsementEvent(String a,String award,Status status,String externalReference,String details,String actor,Instant at){super(a);awardRecordId=requiredText(award,"awardRecordId");this.status=java.util.Objects.requireNonNull(status,"status");this.externalReference=optionalText(externalReference);this.details=requiredText(details,"details");recordedBy=requiredText(actor,"actor");recordedAt=java.util.Objects.requireNonNull(at,"recordedAt");}public String getAwardRecordId(){return awardRecordId;}public Status getStatus(){return status;}public String getExternalReference(){return externalReference;}public String getDetails(){return details;}public String getRecordedBy(){return recordedBy;}public Instant getRecordedAt(){return recordedAt;}}
